<?php

declare(strict_types=1);

namespace Koravik\Platform\Organizations;

use Koravik\Platform\Database\Database;
use Koravik\Platform\Security\Security;
use RuntimeException;

final class OrganizationController
{
    public function __construct(private readonly Database $database) {}

    public function handle(string $method,string $path): bool
    {
        if($method==='GET'&&$path==='/organizations'){$this->index();return true;}
        if($method==='POST'&&$path==='/organizations'){$this->create();return true;}
        if($method==='GET'&&preg_match('#^/organizations/invitations/([A-Za-z0-9_-]+)$#',$path,$m)){$this->accept($m[1]);return true;}
        if($method==='GET'&&preg_match('#^/organizations/([a-f0-9-]{36})$#',$path,$m)){$this->show($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/invitations$#',$path,$m)){$this->invite($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/members/([a-f0-9-]{36})/role$#',$path,$m)){$this->role($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/members/([a-f0-9-]{36})/remove$#',$path,$m)){$this->remove($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/ownership/([a-f0-9-]{36})$#',$path,$m)){$this->transfer($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/events$#',$path,$m)){$this->event($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/links$#',$path,$m)){$this->link($m[1]);return true;}
        if($method==='GET'&&preg_match('#^/organizations/([a-f0-9-]{36})/settings$#',$path,$m)){$this->settings($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/settings$#',$path,$m)){$this->saveSettings($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/lifecycle/(active|suspended|archived)$#',$path,$m)){$this->lifecycle($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/invitations/([a-f0-9-]{36})/(resend|revoke)$#',$path,$m)){$this->invitationAction($m[1],$m[2],$m[3]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/domains$#',$path,$m)){$this->domain($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/teams$#',$path,$m)){$this->team($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/teams/([a-f0-9-]{36})/members$#',$path,$m)){$this->teamMember($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/publish$#',$path,$m)){$this->publish($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/([a-f0-9-]{36})/quest-proposals$#',$path,$m)){$this->questProposal($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/organizations/quest-proposals/([a-f0-9-]{36})/(accepted|declined)$#',$path,$m)){$this->questResponse($m[1],$m[2]);return true;}
        return false;
    }

    private function index():void
    {
        $a=Security::requireAccount();$service=new OrganizationService($this->database);$cards='';foreach($service->memberships((string)$a['id']) as $o){$cards.='<article class="surface"><p class="eyebrow">'.self::e(ucfirst((string)$o['membership_role'])).' · '.self::e(ucfirst((string)$o['status'])).'</p><h2>'.self::e((string)$o['name']).'</h2><p>'.self::e((string)($o['summary']??'')).'</p><a class="button" href="/organizations/'.self::e((string)$o['id']).'">Open organization</a></article>';}
        $body='<section class="page-heading"><div><p class="eyebrow">Organizations</p><h1>Shared work without losing personal ownership.</h1><p>Organizations are optional operating spaces for groups, nonprofits, and communities. Your personal Koravik remains independent.</p></div></section><section class="surface"><h2>Create an organization</h2><form method="post" action="/organizations" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Name<input name="name" required maxlength="180"></label><label>Primary timezone<input name="timezone" value="America/New_York"></label><label class="full">Summary<textarea name="summary"></textarea></label><button class="button" type="submit">Create organization</button></form></section><section><h2>Your organizations</h2><div class="grid">'.($cards?:'<article class="empty-state"><h3>No organizations yet.</h3><p>You can still use every personal Koravik feature without one.</p></article>').'</div></section>';$this->page('Organizations',$body);
    }

    private function show(string $id):void
    {
        $a=Security::requireAccount();$service=new OrganizationService($this->database);try{$data=$service->dashboard((string)$a['id'],$id);}catch(RuntimeException){$this->notFound();return;}$o=$data['organization'];$members='';foreach($data['members'] as $m){$controls='';if($service->can((string)$a['id'],$id,'manage_members')&&$m['role']!=='owner'){$controls='<form method="post" action="/organizations/'.$id.'/members/'.self::e((string)$m['id']).'/role"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><select name="role"><option>admin</option><option>creator</option><option>member</option></select><button class="button secondary">Change role</button></form><form method="post" action="/organizations/'.$id.'/members/'.self::e((string)$m['id']).'/remove"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="button secondary">Remove</button></form>';}$members.='<article class="surface"><h3>'.self::e((string)$m['display_name']).'</h3><p>'.self::e((string)$m['email']).' · '.self::e(ucfirst((string)$m['role'])).'</p>'.$controls.'</article>';}
        $events='';foreach($data['events'] as $e)$events.='<li><a href="/gather/events/'.self::e((string)$e['id']).'">'.self::e((string)$e['title']).'</a> · '.self::e((string)$e['starts_at']).'</li>';
        $links='';foreach($data['links'] as $l)$links.='<li>'.self::e((string)($l['hostname']??'krvk.nl')).'/'.self::e((string)$l['slug']).' · '.self::e((string)$l['label']).'</li>';
        $activity='';foreach($data['activity'] as $x)$activity.='<li>'.self::e((string)$x['action']).' · '.self::e((string)$x['created_at']).' UTC</li>';
        $pending='';foreach($data['invitations'] as $i)$pending.='<li>'.self::e((string)$i['email']).' · '.self::e((string)$i['role']).' · expires '.self::e((string)$i['expires_at']).'<form method="post" action="/organizations/'.$id.'/invitations/'.self::e((string)$i['id']).'/resend"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="quiet-button">Resend</button></form><form method="post" action="/organizations/'.$id.'/invitations/'.self::e((string)$i['id']).'/revoke"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="quiet-button">Revoke</button></form></li>';
        $admin=$service->can((string)$a['id'],$id,'manage_members')?'<section class="surface"><h2>Invite a member</h2><form method="post" action="/organizations/'.$id.'/invitations"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Email<input type="email" name="email" required></label><label>Role<select name="role"><option value="member">Member</option><option value="creator">Creator</option><option value="admin">Admin</option></select></label><button class="button">Send invitation</button></form><h3>Pending invitations</h3><ul>'.($pending?:'<li>No pending invitations.</li>').'</ul></section>':'';
        $creator=$service->can((string)$a['id'],$id,'create_content')?'<section class="grid"><article class="surface"><h2>Create organization event</h2><form method="post" action="/organizations/'.$id.'/events"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Title<input name="title" required></label><label>Starts<input type="datetime-local" name="starts_at" required></label><label>Venue<input name="venue"></label><label>Description<textarea name="description"></textarea></label><input type="hidden" name="guest_registration_enabled" value="1"><input type="hidden" name="waitlist_enabled" value="1"><button class="button">Create event</button></form></article><article class="surface"><h2>Create organization link</h2><form method="post" action="/organizations/'.$id.'/links"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Label<input name="label" required></label><label>Destination<input type="url" name="destination" required></label><button class="button">Create link</button></form></article></section>':'';
        $settings=$service->can((string)$a['id'],$id,'manage_organization')?' · <a href="/organizations/'.$id.'/settings">Settings and operations</a>':'';$mine='';foreach((new OrganizationExpansionService($this->database))->operations((string)$a['id'],$id)['mine'] as $p)$mine.='<article class="surface"><h3>'.self::e((string)$p['title']).'</h3><p>'.self::e((string)$p['description']).'</p><form method="post" action="/organizations/quest-proposals/'.self::e((string)$p['id']).'/accepted"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="button">Accept as personal Quest</button></form><form method="post" action="/organizations/quest-proposals/'.self::e((string)$p['id']).'/declined"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="button secondary">Decline</button></form></article>';
        $capabilities=[];foreach(['create_content'=>'Create content','manage_members'=>'Manage members','manage_domains'=>'Manage domains','manage_organization'=>'Govern organization'] as $cap=>$label)if($service->can((string)$a['id'],$id,$cap))$capabilities[]=$label;
        $summary='<section class="organization-command-bar" aria-label="Organization operating summary"><article><strong>'.count($data['members']).'</strong><span>Active members</span></article><article><strong>'.count($data['events']).'</strong><span>Gather-owned events</span></article><article><strong>'.count($data['links']).'</strong><span>Beacon-owned links</span></article><article><strong>'.count($data['invitations']).'</strong><span>Pending invitations</span></article></section><section class="organization-role-panel"><div><p class="eyebrow">Your operating role</p><h2>'.self::e(ucfirst((string)$o['membership_role'])).'</h2><p>'.self::e($capabilities?implode(' · ',$capabilities):'View shared operations').'</p></div><p>Organization roles apply only here. They do not change your Platform role or transfer ownership of personal records.</p></section>';
        $body='<section class="page-heading organization-heading"><div><p class="eyebrow">Organization · '.self::e(ucfirst((string)$o['membership_role'])).'</p><h1>'.self::e((string)$o['name']).'</h1><p>'.self::e((string)($o['summary']??'')).'</p></div><p><a href="/organizations">All organizations</a>'.$settings.'</p></section>'.$summary.($mine?'<section><h2>Quest proposals for you</h2><div class="grid">'.$mine.'</div></section>':'').'<section class="organization-source-grid"><article class="surface"><p class="eyebrow">Gather owns event truth</p><h2>Upcoming and recent events</h2><ul>'.($events?:'<li>No organization events yet.</li>').'</ul></article><article class="surface"><p class="eyebrow">Beacon owns public links</p><h2>Beacon links</h2><ul>'.($links?:'<li>No organization links yet.</li>').'</ul></article></section>'.$creator.$admin.'<section><h2>Members</h2><div class="grid">'.$members.'</div></section><section class="surface"><h2>Recent activity</h2><ul>'.($activity?:'<li>No activity yet.</li>').'</ul></section>';$this->page((string)$o['name'],$body);
    }

    private function create():void{$this->csrf();$a=Security::requireAccount();try{$id=(new OrganizationService($this->database))->create((string)$a['id'],$_POST);$_SESSION['flash']='Organization created.';$this->go('/organizations/'.$id);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/organizations');}}
    private function invite(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new OrganizationService($this->database))->invite((string)$a['id'],$id,(string)($_POST['email']??''),(string)($_POST['role']??'member'));$_SESSION['flash']='Invitation queued for secure email delivery.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function accept(string $token):void{$a=Security::requireAccount();try{$id=(new OrganizationService($this->database))->acceptInvitation((string)$a['id'],$token);$_SESSION['flash']='Organization invitation accepted.';$this->go('/organizations/'.$id);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/organizations');}}
    private function role(string $id,string $member):void{$this->csrf();$a=Security::requireAccount();try{(new OrganizationService($this->database))->changeRole((string)$a['id'],$id,$member,(string)($_POST['role']??''));$_SESSION['flash']='Membership role updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function remove(string $id,string $member):void{$this->csrf();$a=Security::requireAccount();try{(new OrganizationService($this->database))->removeMember((string)$a['id'],$id,$member);$_SESSION['flash']='Member removed.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function transfer(string $id,string $member):void{$this->csrf();$a=Security::requireAccount();try{(new OrganizationService($this->database))->transferOwnership((string)$a['id'],$id,$member);$_SESSION['flash']='Organization ownership transferred.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function event(string $id):void{$this->csrf();$a=Security::requireAccount();try{$event=(new OrganizationService($this->database))->createOrganizationEvent((string)$a['id'],$id,$_POST);$_SESSION['flash']='Organization event created.';$this->go('/gather/events/'.$event);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/organizations/'.$id);}}
    private function link(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new OrganizationService($this->database))->createOrganizationLink((string)$a['id'],$id,(string)($_POST['label']??''),(string)($_POST['destination']??''));$_SESSION['flash']='Organization Beacon link created.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function settings(string $id):void
    {
        $a=Security::requireAccount();$service=new OrganizationService($this->database);try{$o=$service->organization((string)$a['id'],$id);$ops=(new OrganizationExpansionService($this->database))->operations((string)$a['id'],$id);}catch(RuntimeException){$this->notFound();return;}if(!$service->can((string)$a['id'],$id,'manage_organization')){$this->notFound();return;}$domains='';foreach($ops['domains'] as $d)$domains.='<option value="'.self::e((string)$d['id']).'">'.self::e((string)$d['hostname']).'</option>';$teams='';foreach($ops['teams'] as $t)$teams.='<li>'.self::e((string)$t['name']).' · '.(int)$t['member_count'].' members</li>';$proposals='';foreach($ops['proposals'] as $p)$proposals.='<li>'.self::e((string)$p['title']).' → '.self::e((string)$p['recipient_name']).' · '.self::e((string)$p['status']).'</li>';
        $body='<section class="page-heading"><div><p class="eyebrow">Organization settings</p><h1>'.self::e((string)$o['name']).'</h1><p>Identity, coordination, publishing, lifecycle, and recovery.</p></div><a href="/organizations/'.$id.'">Back</a></section><section class="surface"><h2>Profile and brand</h2><form method="post" action="/organizations/'.$id.'/settings"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Name<input name="name" value="'.self::e((string)$o['name']).'" required></label><label>Public name<input name="public_name" value="'.self::e((string)($o['public_name']??'')).'"></label><label>Summary<textarea name="summary">'.self::e((string)($o['summary']??'')).'</textarea></label><label>Contact email<input type="email" name="contact_email" value="'.self::e((string)($o['contact_email']??'')).'"></label><label>Brand color<input name="brand_color" value="'.self::e((string)($o['brand_color']??'')).'" placeholder="#315c52"></label><label>Timezone<input name="timezone" value="'.self::e((string)$o['primary_timezone']).'"></label><button class="button">Save settings</button></form></section><section class="grid"><article class="surface"><h2>Verified domain</h2><form method="post" action="/organizations/'.$id.'/domains"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><select name="domain_id">'.$domains.'</select><button class="button secondary">Use domain</button></form><h2>Public presence</h2><form method="post" action="/organizations/'.$id.'/publish"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><select name="visibility"><option value="unlisted">Unlisted</option><option value="public">Public</option></select><button class="button">Publish Beacon page</button></form></article><article class="surface"><h2>Teams</h2><ul>'.($teams?:'<li>No teams yet.</li>').'</ul><form method="post" action="/organizations/'.$id.'/teams"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Name<input name="name" required></label><label>Summary<textarea name="summary"></textarea></label><button class="button">Create team</button></form></article></section><section class="surface"><h2>Quest coordination</h2><ul>'.($proposals?:'<li>No Quest proposals yet.</li>').'</ul><form method="post" action="/organizations/'.$id.'/quest-proposals"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Recipient account ID<input name="recipient_account_id" required></label><label>Title<input name="title" required></label><label>Description<textarea name="description"></textarea></label><button class="button">Propose Quest</button></form></section><section class="surface"><h2>Lifecycle and recovery</h2><p>Records remain preserved when an Organization is suspended or archived.</p>'.implode(' ',array_map(fn($s)=>'<form style="display:inline" method="post" action="/organizations/'.$id.'/lifecycle/'.$s.'"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><button class="button secondary">'.ucfirst($s).'</button></form>',['active','suspended','archived'])).'</section>';$this->page('Organization settings',$body);
    }
    private function saveSettings(string $id):void{$this->act($id,function($a,$x):void{(new OrganizationExpansionService($this->database))->updateSettings($a,$x,$_POST);},'Organization settings saved.');}
    private function lifecycle(string $id,string $state):void{$this->act($id,function($a,$x)use($state):void{(new OrganizationExpansionService($this->database))->lifecycle($a,$x,$state);},'Organization lifecycle updated.');}
    private function invitationAction(string $id,string $invitation,string $action):void{$this->csrf();$a=Security::requireAccount();try{$s=new OrganizationExpansionService($this->database);if($action==='revoke')$s->revokeInvitation((string)$a['id'],$id,$invitation);else $s->resendInvitation((string)$a['id'],$id,$invitation,(string)\env('APP_URL','http://127.0.0.1:8080'));$_SESSION['flash']='Invitation updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function domain(string $id):void{$this->act($id,function($a,$x):void{(new OrganizationExpansionService($this->database))->assignDomain($a,$x,(string)($_POST['domain_id']??''));},'Organization domain updated.');}
    private function team(string $id):void{$this->act($id,function($a,$x):void{(new OrganizationExpansionService($this->database))->createTeam($a,$x,(string)($_POST['name']??''),(string)($_POST['summary']??''));},'Team created.');}
    private function teamMember(string $id,string $team):void{$this->act($id,function($a,$x)use($team):void{(new OrganizationExpansionService($this->database))->addTeamMember($a,$x,$team,(string)($_POST['membership_id']??''),(string)($_POST['team_role']??'member'));},'Team membership updated.');}
    private function publish(string $id):void{$this->csrf();$a=Security::requireAccount();try{$page=(new OrganizationExpansionService($this->database))->publishPage((string)$a['id'],$id,(string)($_POST['visibility']??'unlisted'));$_SESSION['flash']='Organization Beacon page published: /beacon/pages/'.$page;}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function questProposal(string $id):void{$this->act($id,function($a,$x):void{(new OrganizationExpansionService($this->database))->proposeQuest($a,$x,(string)($_POST['recipient_account_id']??''),(string)($_POST['title']??''),(string)($_POST['description']??''));},'Quest proposed for member review.');}
    private function questResponse(string $proposal,string $response):void{$this->csrf();$a=Security::requireAccount();try{$quest=(new OrganizationExpansionService($this->database))->respondToQuest((string)$a['id'],$proposal,$response);$_SESSION['flash']=$response==='accepted'?'Quest accepted into your personal Quests.':'Quest proposal declined.';$this->go($quest?'/quests/'.$quest:'/organizations');}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/organizations');}}
    private function act(string $id,callable $action,string $success):void{$this->csrf();$a=Security::requireAccount();try{$action((string)$a['id'],$id);$_SESSION['flash']=$success;}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/organizations/'.$id);}
    private function csrf():void{if(!Security::verifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('Your session token expired.');}
    private function go(string $to):never{header('Location: '.$to,true,303);exit;}
    private function notFound():void{http_response_code(404);$this->page('Organization not found','<section class="empty-state"><h1>That organization is unavailable.</h1></section>');}
    private function page(string $title,string $body):void{$flash='';if(isset($_SESSION['flash'])){$flash='<div class="notice" role="status">'.self::e((string)$_SESSION['flash']).'</div>';unset($_SESSION['flash']);}echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Koravik</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/journey.css"><link rel="stylesheet" href="/assets/organization-dashboard.css"></head><body><main id="main" class="page">'.$flash.$body.'</main><footer>Koravik · Organizations</footer></body></html>';}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
}
